pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict to non-zero amount to ensure there is something to transfer
        vm.assume(amount > 0);
        // Bound to prevent overflow in calculations
        bound(amount, 1, type(uint128).max);

        address owner = c.owner();
        uint256 ownerBefore = owner.balance;

        // Deal and send the amount to trigger the logic
        vm.deal(address(this), amount);
        c.go{value: amount}();

        uint256 ownerAfter = owner.balance;

        // Owner balance must strictly increase because reference transfers contract balance to owner
        // after the external call succeeds (and the call forwards msg.value).
        // The mutant never transfers, so ownerAfter == ownerBefore for the buggy version.
        assertTrue(ownerAfter > ownerBefore);
    }
}

