pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // restrict to admissible positive value that does not overflow typical balances
        vm.assume(amount > 0 && amount < 1e60);
        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        // record balances before the call
        uint256 balTargetBefore = target.balance;
        uint256 balCBefore = address(c).balance;
        // fund caller and call go() with fuzzed value
        vm.deal(address(this), amount);
        c.go{value: amount}();
        // after the call, the sum of balances of the contract and the target
        // must equal the previous sum plus the value sent.
        uint256 balTargetAfter = target.balance;
        uint256 balCAfter = address(c).balance;
        assertTrue(balTargetAfter + balCAfter == balTargetBefore + balCBefore + amount);
    }
}

